Here's a modern MSTest test class for `DataFetcher`:

```csharp
using System.Net;
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class DataFetcherTests
{
    // Modern MSTest uses [Timeout] at method level (in milliseconds)
    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        // Use a custom handler to mock HttpClient without external libraries
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("hello world")
            });

        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        string result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_OnNonSuccessStatusCode()
    {
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.InternalServerError));

        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_Throws_WhenCancelled()
    {
        // Handler that delays long enough for cancellation to fire
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.OK),
            delay: TimeSpan.FromSeconds(10));

        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();

        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_PassesCancellationToken_ToHttpClient()
    {
        var handler = new MockHttpMessageHandler(
            new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent("ok")
            });

        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);
        using var cts = new CancellationTokenSource();

        await fetcher.FetchAsync("https://example.com", cts.Token);

        // Verify the token was forwarded
        Assert.AreEqual(cts.Token, handler.ReceivedCancellationToken);
    }

    // Minimal test double — no mocking library needed
    private class MockHttpMessageHandler : HttpMessageHandler
    {
        private readonly HttpResponseMessage _response;
        private readonly TimeSpan _delay;

        public CancellationToken ReceivedCancellationToken { get; private set; }

        public MockHttpMessageHandler(HttpResponseMessage response, TimeSpan delay = default)
        {
            _response = response;
            _delay = delay;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            ReceivedCancellationToken = cancellationToken;

            if (_delay > TimeSpan.Zero)
                await Task.Delay(_delay, cancellationToken);

            return _response;
        }
    }
}
```

**Key patterns demonstrated:**

- **`async Task` test methods** — MSTest natively awaits them; never use `async void`
- **`[Timeout(ms)]`** — guards against hanging tests; applied per-method
- **`Assert.ThrowsExceptionAsync<T>`** — the async counterpart for exception assertions
- **`CancellationTokenSource`** — test both pre-cancelled and flowing-token scenarios
- **Custom `HttpMessageHandler`** — avoids mocking libraries entirely; gives full control over `HttpClient` behavior
